<?php require_once __DIR__.'/../config.php';header('Content-Type: application/json; charset=utf-8');try{$rows=db()->query('SELECT id,name,description,category,price,stock,active FROM products WHERE active=1 ORDER BY id')->fetchAll();echo json_encode(['products'=>$rows],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(500);echo json_encode(['error'=>'Database unavailable']);}